import React, { useState } from 'react';

const StudentProfile = () => {
  const [links, setLinks] = useState({ github: '', portfolio: '' });

  return (
    <div className="max-w-4xl mx-auto p-6 bg-white shadow-lg rounded-xl mt-10 text-right" dir="rtl">
      <h2 className="text-2xl font-bold mb-6 text-indigo-700 border-b pb-4">
        إعداد الملف الشخصي الرقمي (Digital CV)
      </h2>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
        <div>
          <label className="block text-sm font-semibold text-gray-700 mb-2">رابط GitHub:</label>
          <input 
            type="url"
            value={links.github}
            placeholder="https://github.com/username"
            className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none"
            onChange={(e) => setLinks({ ...links, github: e.target.value })}
          />
        </div>
      </div>

      <button className="w-full py-3 bg-indigo-600 text-white rounded-lg font-bold hover:bg-indigo-700">
        حفظ التغييرات
      </button>
    </div>
  );
};

export default StudentProfile;
